/// <summary>
/// CB788_CustomPricingComponents
/// Price component table
/// </summary>
public class METSalesLinePriceComponent extends common
{
}

Method.Source:
    /// <summary>
    /// Find a price component record
    /// </summary>
    /// <param name = "_inventTransId">The <c>InventTransId</c> value to retrieve the price component record.</param>
    /// <param name = "_component">The <c>METComponent</c> value to retrieve the price component record.</param>
    /// <param name = "_forUpdate">Specifies if record is selected for update</param>
    /// <returns>Found price component record; otherwise, blank.</returns>
    static METSalesLinePriceComponent find(InventTransId _inventTransId,
                                           METComponent  _component,
                                           boolean       _forUpdate = false)
    {
        METSalesLinePriceComponent priceComponent;

        if (_inventTransId && _component)
        {
            if (_forUpdate)
            {
                priceComponent.selectForUpdate(_forUpdate);
            }

            select firstonly priceComponent
                       where priceComponent.InventTransId == _inventTransId
                          && priceComponent.Component     == _component;
        }

        return priceComponent;
    }

/// <summary>
///    Checks whether a price component record exists.
/// </summary>
/// <param name="_inventTransId">
///    The <c>InventTransId</c> value to retrieve the price component record.
/// </param>
/// <param name="_component">
///    The <c>METComponent</c> value to retrieve the price component record.
/// </param>
/// <returns>
///    true if the price component record exists; otherwise, false.
/// </returns>
static boolean exist(InventTransId _inventTransId, METComponent _component)
{
    return _inventTransId &&
           _component &&
           (select firstonly RecId from METSalesLinePriceComponent
                                  where METSalesLinePriceComponent.InventTransId == _inventTransId
                                     && METSalesLinePriceComponent.Component == _component).RecId != 0;
}
